SELECT CASE WHEN a.balance >= 88000 THEN 'high' WHEN a.balance >= 10000 THEN 'mid' ELSE 'low' END AS balance_bucket, CONCAT_WS(', ', SORT_ARRAY(COLLECT_SET(t.txn_type))) AS txn_type_values FROM transactions t LEFT JOIN accounts a ON a.id = t.account_id INNER JOIN customers c ON a.customer_id = c.id GROUP BY CASE WHEN a.balance >= 88000 THEN 'high' WHEN a.balance >= 10000 THEN 'mid' ELSE 'low' END ORDER BY txn_type_values
